{
  "report": "Resumo executivo (até 2024-05-02): sinal Neutro com viés levemente baixista no curtíssimo prazo. A ação esteve em um rali entre nov-dez/2023 e iniciou uma fase de consolidação desde janeiro/2024. A média de longo prazo (MM200) mantém inclinação positiva e o preço segue levemente acima dela, o que preserva um viés estrutural de alta de longo prazo. No curto/médio prazo, porém, as médias mais rápidas (MM20 e EMA9/EMA21) se aproximaram e a MM20 aparece ligeiramente abaixo da MM50, indicando lateralidade com leve pressão vendedora.",
  "signal": "Neutro",
  "support_levels": [
    12.00,
    11.00,
    10.50
  ],
  "resistance_levels": [
    13.00,
    13.50,
    14.00
  ],
  "indicator_readings": [
    {
      "indicator": "Fechamento",
      "reading": "≈ R$12,50",
      "interpretation": "Preço perto das médias móveis — demonstra indecisão e ausência de tendência direcional forte."
    },
    {
      "indicator": "MM20",
      "reading": "≈ R$12,55",
      "interpretation": "Ligeiramente abaixo da MM50; sinal de curto prazo neutro/levemente negativo."
    },
    {
      "indicator": "MM50",
      "reading": "≈ R$12,95",
      "interpretation": "Achatada — aponta consolidação no médio prazo."
    },
    {
      "indicator": "MM200",
      "reading": "≈ R$12,25",
      "interpretation": "Inclinação suave para cima; mantém suporte estrutural de longo prazo."
    },
    {
      "indicator": "EMA9",
      "reading": "≈ R$12,50",
      "interpretation": "Rápida e convergente com EMA21, sem cruzamento direcional claro."
    },
    {
      "indicator": "EMA21",
      "reading": "≈ R$12,52",
      "interpretation": "Convergente com EMA9 — confirma momento de indecisão no curto prazo."
    },
    {
      "indicator": "MACD",
      "reading": "≈ 0 (próximo de zero)",
      "interpretation": "Linha MACD muito próxima da linha de sinal; histograma quase neutro → momentum fraco/indefinido."
    },
    {
      "indicator": "Histograma MACD",
      "reading": "pequeno (≈ 0)",
      "interpretation": "Oscilações de baixa amplitude indicam falta de força nos movimentos recentes."
    },
    {
      "indicator": "RSI14",
      "reading": "≈ 48",
      "interpretation": "Neutro — sem sobrecompra/sobrevenda; confirma consolidação."
    },
    {
      "indicator": "Bandas de Bollinger (20, 2σ)",
      "reading": "bandas moderadamente estreitas",
      "interpretation": "Volatilidade reduziu em relação ao pico de dez/jan — padrão de consolidação; possível pressão acumulada para um movimento futuro."
    },
    {
      "indicator": "Volume",
      "reading": "abaixo dos picos recentes",
      "interpretation": "Grandes picos ocorreram, mas movimentos de alta recentes não tiveram volume consistente de confirmação — baixa convicção nas recuperações."
    }
  ]
}
